<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Event; use Illuminate\Http\Request; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Str;
class EventController {
 public function index(Request $r){if($r->user())return response()->json(Event::with('creator')->latest('starts_at')->paginate(30));return response()->json(Cache::remember('public.events',60,fn()=>Event::where('status','published')->where('starts_at','>=',now()->subDay())->orderBy('starts_at')->get()));}
 public function store(Request $r){abort_unless($r->user()->canManage('events.create'),403);$d=$r->validate(['title'=>'required|string|max:255','slug'=>'nullable|string|max:255|unique:events,slug','excerpt'=>'nullable|string|max:1000','description'=>'nullable|string','starts_at'=>'required|date','ends_at'=>'nullable|date|after:starts_at','location'=>'nullable|string|max:255','status'=>'nullable|in:draft,published,archived','featured'=>'boolean','seo'=>'nullable|array']);$d['slug']=$d['slug']??Str::slug($d['title']);$d['created_by']=$r->user()->id;$e=Event::create($d);Cache::forget('public.events');return response()->json($e,201);}
 public function update(Request $r,Event $event){abort_unless($r->user()->canManage('events.edit'),403);$event->update($r->validate(['title'=>'sometimes|required|string|max:255','slug'=>'sometimes|required|string|max:255|unique:events,slug,'.$event->id,'excerpt'=>'nullable|string|max:1000','description'=>'nullable|string','starts_at'=>'sometimes|required|date','ends_at'=>'nullable|date|after:starts_at','location'=>'nullable|string|max:255','status'=>'sometimes|in:draft,published,archived','featured'=>'boolean','seo'=>'nullable|array']));Cache::forget('public.events');return response()->json($event->fresh());}
 public function destroy(Request $r,Event $event){abort_unless($r->user()->canManage('events.delete'),403);$event->delete();Cache::forget('public.events');return response()->noContent();}
}